```ts
// l2rank#1 (chunk 51, round two's last look): a box someone else put in Lovejoin under a Seedelf's register copied
// as found (d = 1) comes back classed received:<tx> (lovejoin.ts withdrawOne, `received ? receivedIn(...)`). Purpose::Mint
// ranks Received 1, with money others paid, and step 1 takes the smallest single that pays (build.rs one_more), so
// the next stealth mint spends that way back before Bob's 20 ₳ payment. The withdraw spent a box carrying the
// Seedelf's own register, byte for byte, so anyone can tie the new Seedelf to that Seedelf. gap-g1#1 (a) gives a d = 1
// copy paid into the contract Unknown (activity.ts classes), but its match reads the view's contract rows alone: the
// way back's register is fresh, and nothing reads the box's.
import { describe, expect, it } from "vitest";

import { CONTRACT_V1 } from "../src/background/balances";
import { txInputs } from "../src/background/cbor";
import { Collateral } from "../src/background/collateral";
import type { KoiosUtxo } from "../src/background/koios";
import { LovejoinService } from "../src/background/lovejoin";
import { SESSION_MINT } from "../src/background/mint";
import { CHAINS, withSession, type Tested } from "./chain-fixtures";
import { preprodAddress } from "./fixtures/bech32";
import { txIdOf } from "./fixtures/cbor";
import { loadTestWasm, ownedUtxos } from "./fakes";
import { ADA, ADA_POOL, adaBox } from "./v2-pools";

const hash = (h: string) => (h.length === 64 ? h : h.repeat(32));
const inputsOf = (cbor: string) => txInputs(Uint8Array.from(Buffer.from(cbor, "hex")));
const inAda = (txHash: string, txIndex = 0) => ({ txHash, txIndex, pool: ADA });
const ref = (b: { txHash: string; txIndex: number }) => `${b.txHash}#${b.txIndex}`;
/** A deposit's inputs, as tx_info lists them: one UTxO at an address of payment key `cred`. */
const paidBy = (cred: string) => [{ payment_addr: { bech32: preprodAddress(cred), cred } }];

type Entry = { txHash: string; kind: string; lovelace: string; origin?: { id: string; origin: string } };
const entryOf = async (t: Tested, txHash: string) =>
  (await t.store.get<{ entries: Entry[] }>("history.preprod"))!.entries.find((e) => e.txHash === txHash);

/** A UTxO of the wallet's at the Seedelf contract, `txHash#index`, under a fresh re-randomization of its register. */
async function privateRow(t: Tested, txHash: string, lovelace: string, index = 0): Promise<KoiosUtxo> {
  const wasm = loadTestWasm();
  const bytes = await t.wallet.withKeys((keys) => Buffer.from(wasm.registerToDatum(wasm.rerandomize(keys.seedelf.baseRegister()))).toString("hex"));
  return { ...ownedUtxos[0]!, tx_hash: txHash, tx_index: index, value: lovelace, asset_list: [], inline_datum: { bytes, value: null }, block_height: 9_000_001 };
}

/** Lovejoin on `t`'s fakes, reading the 5 ₳ pool, giveme.my's witness stood in for (as b15-first-picks.test.ts). */
function witnessed(t: Tested) {
  const wasm = loadTestWasm();
  t.collateral.answer = { status: 200, body: { witness: "a1008182" } };
  return new LovejoinService({
    ...t.deps,
    wasm: {
      ...wasm,
      finishLovejoinWithdraw: (request: string) => {
        const { txCbor } = JSON.parse(request) as { txCbor: string };
        return JSON.stringify({ txCbor, txHash: txIdOf(Uint8Array.from(Buffer.from(txCbor, "hex"))) });
      },
    } as typeof wasm,
    collateral: () => new Collateral("https://www.giveme.my/preprod/collateral/", t.collateral.fetch),
    store: t.store,
    pools: async () => [ADA_POOL],
    sessionIndices: async () => [0],
  });
}

/** `rows` land in the private balance; then what a stealth mint from it spends. */
async function stealthMint(t: Tested, rows: KoiosUtxo[]): Promise<string[]> {
  t.koios.added.push(...rows);
  t.clock.now += 60_000;
  await t.balances.get("preprod", true);
  await t.mint.build("preprod", "", "seedelf");
  return inputsOf((await t.session.get<{ txCbor: string }>(SESSION_MINT))!.txCbor);
}

/** Mallory's 5 ₳ box under Seedelf S1's register as found (d = 1), paid from her own key; S1's row as the view has it. */
async function planted(tx: string) {
  const { t } = await withSession("40000000");
  await t.balances.get("preprod");
  const s1 = ownedUtxos.find((u) => (u.asset_list ?? []).some((a) => a.policy_id === CONTRACT_V1.seedelfPolicyId))!;
  const C = hash(tx);
  t.koios.addedToAccounts.push(adaBox(C, s1.inline_datum!.bytes, t.clock.now));
  t.koios.txSpends.set(C, paidBy("ee".repeat(28)));
  const lj = witnessed(t);
  const pool = (await lj.status("preprod")).pools!.find((p) => p.id === ADA)!;
  // The wallet holds it as someone else's: the key's check owns it, no key of the phrase paid its deposit.
  expect((pool.someoneElse ?? []).map(ref)).toEqual([ref(inAda(C))]);
  return { t, lj, C, s1 };
}

/** The way back `back` made, as its entry has it, a stealth mint beside Bob's 20 ₳ payment, and what that mint spends. */
async function mintAfter(t: Tested, back: { txHash: string }, C: string) {
  const entry = (await entryOf(t, back.txHash))!;
  // Anyone reading S1's name sees its register in the box this withdraw spent, on chain.
  const withdraw = t.koios.submitted.find((bytes) => txIdOf(bytes) === back.txHash)!;
  expect(txInputs(withdraw)).toContain(`${C}#0`);
  const w = await privateRow(t, back.txHash, entry.lovelace);
  const bob = await privateRow(t, hash("b0"), "20000000");
  const spent = await stealthMint(t, [w, bob]);
  return { entry, w, bob, spent, C };
}

describe("l2rank#1: a box put in under a Seedelf's register as found, brought back (chunk 51, round two's last look)", CHAINS, () => {
  it("Bring every box back now: its way back ranks with payments, and the next stealth mint takes it before Bob's 20 ₳", { timeout: 60_000 }, async () => {
    const { t, lj, C } = await planted("c9");
    await lj.bringAllBack("preprod");
    const sent = await lj.withdrawDue("preprod");
    expect(sent).toHaveLength(1);
    const { entry, w, bob, spent } = await mintAfter(t, sent[0]!, C);
    console.log("way back", sent[0]!.txHash, "lovelace", entry.lovelace, "origin", JSON.stringify(entry.origin));
    console.log("stealth mint spent", JSON.stringify(spent), "W =", `${w.tx_hash}#0`, "Bob =", `${bob.tx_hash}#0`);
    // Its making is public (the box carried S1's register byte for byte): never ranked with money paid properly.
    expect.soft(entry.origin?.origin, "the way back of a d = 1 planted box").not.toBe("received");
    expect(spent, "the stealth mint should take Bob's payment, not the publicly tied way back").toEqual([`${bob.tx_hash}#0`]);
  });

  it("another device's session past GAP_LIMIT: its deposit's way back is sealed received, not that session's", { timeout: 60_000 }, async () => {
    const { t } = await withSession("40000000");
    await t.balances.get("preprod");
    const A = hash("a9");
    const wasm = loadTestWasm();
    const datum = await t.wallet.withKeys((keys) => Buffer.from(wasm.registerToDatum(wasm.rerandomize(keys.seedelf.baseRegister()))).toString("hex"));
    t.koios.addedToAccounts.push(adaBox(A, datum, t.clock.now));
    // Session 25's one-time account paid it: this device's book knows session 0 alone (witnessed's sessionIndices).
    t.koios.txSpends.set(A, paidBy(await t.wallet.withKeys((k) => k.oneTime.keyHash(25))));
    const lj = witnessed(t);
    expect(((await lj.status("preprod")).pools!.find((p) => p.id === ADA)!.someoneElse ?? []).map(ref)).toEqual([ref(inAda(A))]);
    const back = await lj.withdrawNow("preprod", inAda(A), true);
    const entry = (await entryOf(t, back.txHash))!;
    console.log("session 25's way back", JSON.stringify(entry.origin));
    // someoneElsesOf's comment says this "only leaves its box out of Mix my boxes again".
    expect(entry.origin?.origin, "a deposit anyone can follow to a session, brought back").not.toBe("received");
  });

  it("Bring one back anyway: the same", { timeout: 60_000 }, async () => {
    const { t, lj, C } = await planted("ca");
    const back = await lj.withdrawNow("preprod", inAda(C), true);
    const { entry, w, bob, spent } = await mintAfter(t, back, C);
    console.log("way back", back.txHash, "lovelace", entry.lovelace, "origin", JSON.stringify(entry.origin));
    console.log("stealth mint spent", JSON.stringify(spent), "W =", `${w.tx_hash}#0`, "Bob =", `${bob.tx_hash}#0`);
    expect.soft(entry.origin?.origin, "the way back of a d = 1 planted box").not.toBe("received");
    expect(spent, "the stealth mint should take Bob's payment, not the publicly tied way back").toEqual([`${bob.tx_hash}#0`]);
  });
});
```

