describe("l2rank#2: what the code does (passes on HEAD)", () => {
  it("a box 1.9.1 brought back (no origin) goes after Bob's payment: the stealth mint spends the payment", { timeout: 60_000 }, async () => {
    const t = await wallet();
    const old = await boxBack(t, "4800000", hash("bb"));            // withdraw entry with no origin, as 1.9.1 wrote it
    const bob = await privateRow(t, hash("b0"), "20000000");
    const classes = await t.activity.classes("preprod", [old, bob]);
    expect(classes.get(`${old.tx_hash}#0`)).toEqual({ id: `box:${old.tx_hash}`, origin: "lovejoin" });
    expect(await stealthMint(t, [old, bob])).toEqual([`${bob.tx_hash}#0`]);
  });
  it("a box recorded as mixed goes first, before Bob's payment", { timeout: 60_000 }, async () => {
    const t = await wallet();
    const box = await boxBack(t, "4800000", hash("bc"), { id: `box:${hash("bc")}`, origin: "mixed" });
    const bob = await privateRow(t, hash("b0"), "20000000");
    expect(await stealthMint(t, [box, bob])).toEqual([`${box.tx_hash}#0`]);   // the same 4.8 ₳ box pays alone
  });
});
function orderClaims(file: string) {
  const text = readFileSync(new URL(file, import.meta.url), "utf8");
  return text.split("\n").flatMap((line, i) =>
    /first[^.]*, then (?:money you received|received money)/.test(line)
      ? [{ at: `${file.replace(/^.*\//, "")}:${i + 1}`, qualified: /record/.test(line) }] : []);
}
describe("l2rank#2: what the docs say", () => {
  const files = ["../../docs/privacy.md", "../../docs/architecture.md", "../../docs/flows.md", "../../wasm/README.md"];
  it("every line that puts a box before received money for a stealth mint says only a box the wallet recorded a mix moving goes first", () => {
    const claims = files.flatMap(orderClaims);
    expect(claims.length).toBeGreaterThan(0);
    expect(claims.filter((c) => !c.qualified).map((c) => c.at), "lines claiming any box back from a mix goes first, wider than Purpose::Mint (Mixed 0, Received 1, Lovejoin 2)").toEqual([]);
  });
  it("architecture.md's Picking inputs names Origin::Mixed (or a box marked mixed) as what `Mint` takes first", () => {
    const text = readFileSync(new URL("../../docs/architecture.md", import.meta.url), "utf8");
    const clause = /`Mint` \([^)]*\)[^;]*/.exec(text.split("\n").find((l) => l.includes("**Picking inputs**"))!)![0];
    expect(clause).toMatch(/Origin::Mixed|`mixed`|marked|record/);
  });
});
