    expect(after.depositors).toBeUndefined();               // passes on HEAD
    await lj.releaseBootstrap("preprod", ADA);
    await bringBack(t, lj, X);
    expect((await schedule(t)).mixes ?? []).toEqual([]);    // passes: closed by count
    const { back, entry: written, row } = await bringBack(t, lj, D);
    expect.soft(written.origin).toEqual({ id: `box:${back.txHash}+session:4`, origin: "session" });
    const bob = await privateRow(t, hash("b0"), "60000000");
    expect(await stealthMint(t, [row, bob])).toEqual([`${bob.tx_hash}#0`]);
  });

  it("two Bootstraps released together, the younger's box moved by someone's mix: the older (private) one's box is still session 4's money", async () => {
    const { t } = await withSession("40000000");
    const [D1, R1, D2, X] = [hash("e3"), hash("e4"), hash("e5"), hash("f3")];
