    const datum = await ownDatum(t.wallet);
    t.koios.addedToAccounts.push(adaBox(D1, datum, t.clock.now), adaBox(X, datum, t.clock.now));
    madeByAdaMix(t.koios, X);
    await t.store.set("lovejoin.preprod", { due: [], chains: [older.chain], mixes: [older.entry, younger] });
    const lj = witnessed(t);
    await lj.status("preprod");
    expect((await schedule(t)).chains).toEqual([]);
    await lj.releaseBootstrap("preprod", ADA);
    await bringBack(t, lj, X);
    expect(((await schedule(t)).mixes ?? []).map((e) => e.id)).toEqual([D2]);  // passes: X credited to the older
    const { back, entry: written } = await bringBack(t, lj, D1);
    expect(written.origin).toEqual({ id: `box:${back.txHash}+session:4`, origin: "session" });
  });
});
