```ts
describe("l2sign#1: the page that spared the site leaves before it asks", () => {
  const DECLINED_WAIT = { code: APIError.Refused, info: "The user declined this site just now. It can ask again in 10 s." };
  async function enableMeets(t: Awaited<ReturnType<typeof on>>): Promise<unknown> {
    const s = page();
    const asked = () => t.dapp.approvals().some((a) => a.kind === "connect") || t.dapp.unlockingSites().length > 0;
    const before = asked();
    let heard: unknown;
    const enabling = t.dapp.call(s, "enable", []).then(() => (heard = "connected"), (e: { failure: unknown }) => (heard = e.failure));
    for (let i = 0; i < 200 && heard === undefined && (before || !asked()); i++) await new Promise((r) => setTimeout(r, 0));
    if (heard !== undefined) return heard;
    t.dapp.gone(s);
    await enabling;
    return "asked";
  }
  /** Holds every read of the sealed `dapps` record from the `from`-th on (1-based) until released. */
  function holdSites(t: Awaited<ReturnType<typeof on>>, from = 1) {
    const realGet = t.store.get.bind(t.store) as (name: string) => Promise<unknown>;
    let release!: () => void;
    const gate = new Promise<void>((r) => (release = r));
    const state = { reads: 0 };
    t.store.get = (async (name: string) => {
      if (name === "dapps" && ++state.reads >= from) await gate;
      return realGet(name);
    }) as typeof t.store.get;
    return { state, done: () => { release(); t.store.get = realGet as typeof t.store.get; } };
  }

  it("unlocked, held in its sealed read of the sites: first leaves, then second: the site is turned away", async () => {
    const t = await on();
    const first = page();
    const second = page();
    const enablingFirst = t.dapp.call(first, "enable", []);
    await until(() => t.dapp.approvals().length === 1);
    const hold = holdSites(t);
    const enablingSecond = t.dapp.call(second, "enable", []).catch((e: { failure: unknown }) => e.failure);
    await until(() => hold.state.reads === 1);
    t.dapp.gone(first);
    await expect(enablingFirst).rejects.toMatchObject({ failure: { info: "The page went away." } });
    t.dapp.gone(second);
    hold.done();
    expect(await enablingSecond).toMatchObject({ code: APIError.Refused });
    expect(t.dapp.approvals()).toEqual([]);
    const shown = t.dappWindow.shown;
    expect.soft(await t.dapp.declined(), "the site listed as declined").toEqual([{ origin: ORIGIN, until: expect.any(Number), title: "Example" }]);
    expect.soft(await enableMeets(t), "a reload's page, right after").toEqual(DECLINED_WAIT);
    expect.soft(t.dappWindow.shown, "the window brought back by a reload").toBe(shown);
  });

  it("locked, held at its first read: first leaves its unlock wait, then second: the site is turned away", async () => {
    const t = await on();
    await t.wallet.lock();
    const first = page();
    const second = page();
    const enablingFirst = t.dapp.call(first, "enable", []);
    await until(() => t.dapp.unlockingSites().length === 1);
    const realGet = t.preferences.get.bind(t.preferences);
    let release!: () => void;
    const gate = new Promise<void>((r) => (release = r));
    let held = 0;
    t.preferences.get = (async () => { if (held++ === 0) await gate; return realGet(); }) as typeof t.preferences.get;
    const enablingSecond = t.dapp.call(second, "enable", []).catch((e: { failure: unknown }) => e.failure);
    await until(() => held === 1);
    t.dapp.gone(first);
    await expect(enablingFirst).rejects.toMatchObject({ failure: { info: "The page went away." } });
    t.dapp.gone(second);
    release();
    t.preferences.get = realGet;
    expect(await enablingSecond).toMatchObject({ code: APIError.Refused });
    expect(t.dapp.unlockingSites()).toEqual([]);
    const shown = t.dappWindow.shown;
    expect.soft(await enableMeets(t), "a reload's page, right after").toEqual(DECLINED_WAIT);
    expect.soft(t.dappWindow.shown, "the unlock window brought back by a reload").toBe(shown);
  });

  it("already sharing the question, it leaves while it goes back to ask itself: the site is turned away", async () => {
    const t = await on();
    const first = page();
    const second = page();
    const enablingFirst = t.dapp.call(first, "enable", []);
    await until(() => t.dapp.approvals().length === 1);
    const hold = holdSites(t, 2);
    const enablingSecond = t.dapp.call(second, "enable", []).catch((e: { failure: unknown }) => e.failure);
    await until(() => hold.state.reads === 1);
    for (let i = 0; i < 20; i++) await new Promise((r) => setTimeout(r, 0));
    expect(t.dapp.approvals()).toHaveLength(1);
    t.dapp.gone(first);
    await expect(enablingFirst).rejects.toMatchObject({ failure: { info: "The page went away." } });
    await until(() => hold.state.reads === 2);
    t.dapp.gone(second);
    hold.done();
    expect(await enablingSecond).toMatchObject({ code: APIError.Refused });
    expect(t.dapp.approvals()).toEqual([]);
    expect.soft(await t.dapp.declined(), "the site listed as declined").toEqual([{ origin: ORIGIN, until: expect.any(Number), title: "Example" }]);
    expect.soft(await enableMeets(t), "a reload's page, right after").toEqual(DECLINED_WAIT);
