```ts
// l2docs#2 (the last look at round two of chunk 51's owner's calls, the docs lens). Chunk 51's record,
// docs/archive/plans/review-51.md, is the record the backlog points to once a ❓ line goes ("its plan is the record"),
// and its IDs table is what "chunk 51, <id>" resolves through. Two things must hold on the branch that ships it:
// - every owner's letter (B1 to B16) and answer (1 to 4) the code, the tests, the docs or the config cite is defined
//   in the record, so a later reader can resolve "the owner's answer 4 to B15" without the lead's scratchpad;
// - what the record says this branch ships agrees with the tree: the CLI release's version, and where the owner's
//   calls went once the backlog's six ❓ lines were deleted (the errata rule: the old lines stay, a dated section
//   after them says what changed).
import { readdirSync, readFileSync, statSync } from "node:fs";
import { join, relative, sep } from "node:path";
import { fileURLToPath } from "node:url";

import { describe, expect, it } from "vitest";

const ROOT = fileURLToPath(new URL("../../../../", import.meta.url));
const PLATFORM = join(ROOT, "seedelf-platform");
const DOCS = join(PLATFORM, "seedelf-web-wallet", "docs");
const ARCHIVE = join(DOCS, "archive");
const RECORD = join(ARCHIVE, "plans", "review-51.md");
const BACKLOG = join(DOCS, "backlog.md");

const SKIP = new Set(["node_modules", "target", "dist", "test-results", "pkg", ".git"]);
const TEXT = /\.(ts|tsx|rs|md|ya?ml|mjs|js|sh|toml)$/;
const SELF = "l2docs-2-record.test.ts";

/** Every text file under `dir`, the docs' archive (older records) and this test left out. */
function files(dir: string): string[] {
  return readdirSync(dir).flatMap((name) => {
    const path = join(dir, name);
    if (SKIP.has(name) || path === ARCHIVE || name === SELF) return [];
    if (statSync(path).isDirectory()) return files(path);
    return TEXT.test(name) ? [path] : [];
  });
}

const LETTER = "B(?:1[0-6]|[1-9])";
// The forms the round wrote, each naming one of the owner's calls by its letter.
const LETTER_FORMS = [
  `[Tt]he owner's (?:call,? )?(${LETTER})\\b`, // "the owner's B16", "the owner's call, B13"
  `[Tt]he owner's call \\((${LETTER})\\b`, // "The owner's call (B15)", "(B5 = a)"
  `answers? \\d(?: and \\d)? to (${LETTER})\\b`, // "the owner's answer 4 to B15"
  `chunk 51, (${LETTER})\\b`, // "(chunk 51, B15, ...)", "(chunk 51, B9)"
  `\\b(${LETTER}) = \\(?[abc]\\)?`, // "B1 = (b)", "B6 = (a)"
  `\\b(${LETTER}) \\([abc]\\), the owner`, // "B9 (a), the owner"
  `as before (${LETTER})\\b`, // "as before B15"
  `2026-11-18,? \\(?(${LETTER})\\b`, // "of 2026-11-18 (B16)", "(the owner, 2026-11-18, B9"
  `\\((${LETTER}), the owner's`, // "(B15, the owner's answers of 2026-11-18)"
  `\\.tsx, (${LETTER})\\)`, // "(PhraseGrid.tsx, B9)"
].map((f) => new RegExp(f, "g"));
const ANSWER_FORMS = [/[Tt]he owner's answers? (\d)(?: and (\d))?/g, /\(answer (\d)\)/g];

/** A comment's text, its marker gone, so a citation that wraps reads as one line with the next. */
const prose = (line: string) => line.replace(/^\s*(?:\/\/[/!]?|\*|#)\s?/, "").trim();

/** What `lines` cite, each with its 1-based line: a citation that starts on a line is that line's, wrapped or not. */
function scan(lines: string[]): Array<{ what: string; line: number }> {
  const found = new Map<string, { what: string; line: number }>();
  lines.forEach((line, i) => {
    const own = prose(line);
    const window = `${own} ${prose(lines[i + 1] ?? "")}`;
    const mine = (m: RegExpMatchArray) => (m.index ?? 0) < own.length;
    for (const form of LETTER_FORMS)
      for (const m of window.matchAll(form)) if (mine(m)) found.set(`${m[1]}@${i}`, { what: m[1], line: i + 1 });
    for (const form of ANSWER_FORMS)
      for (const m of window.matchAll(form))
        if (mine(m))
          for (const n of [m[1], m[2]].filter(Boolean)) found.set(`answer ${n}@${i}`, { what: `answer ${n}`, line: i + 1 });
  });
  return [...found.values()];
}

/** Whether the record defines `what`: a table row, a bullet, or a bold or code label that starts with it, or "B15 =". */
function defines(record: string, what: string): boolean {
  const answer = what.startsWith("answer");
  const w = `${what.replace(" ", "\\s+")}\\b${answer ? "" : "(?!#)"}`;
  const label = `(?:^\\s*(?:[-*]|\\d+\\.)\\s+(?:\\*\\*|\`)?|\\|\\s*(?:\\*\\*|\`)?|\\*\\*|\`)${w}|${w}\\s*[=:]`;
  return new RegExp(label, answer ? "im" : "m").test(record);
}

describe("chunk 51's record, on the branch that ships it (l2docs#2)", () => {
  const record = readFileSync(RECORD, "utf8");

  it("reads every form the round cites a call in", () => {
    const sample = [
      "# change (chunk 51, G8's notes; the owner's call, B13).",
      "/// (chunk 51, the owner's answer 4 to B15, time#1).",
      "// back before it kept one, after received money, as before B15 (chunk 51, the owner's answer 4). What a",
      "// spend of the wallet's own left is tied to that spend, and ranks as a session's money (answer 2).",
      "- **Two more** (chunk 51, B15, the owner's answers 2 and 4), so",
      "// words. The rest of the wallet translates, disclosed (the owner, 2026-11-18,",
      "// B9, reversing the 2026-10-06 call, C22, for the phrase's words alone; chunk",
      "// (2026-11-18, B1 = (b)): it was decided with them in chunk 8",
      "// user's own that ties it to the public account. The owner's call (B5 = a): the window",
      "//!   contract's) is payable too, by the owner's call of 2026-11-18 (B16):",
      "/// Chunk 51, gap-g8#6 (the owner's B2, 2026-11-18): a pool's start refuses",
      "  const [B1, B2, MIXED, MOVED] = [\"b1\", \"b2\", \"a1\", \"f9\"]; // a test's own names, never a call",
    ];
    const whats = [...new Set(scan(sample).map((c) => c.what))].sort();
    expect(whats).toEqual(["B1", "B13", "B15", "B16", "B2", "B5", "B9", "answer 2", "answer 4"]);
    expect(defines("1. lanes: R1 to R4, B1 (the build and CI), D1\n| `b1#`, `d1#` | the build and CI |", "B1")).toBe(false);
    expect(defines("| B15 | gap-g1#1 (b) | the stealth mint takes a mixed box first |", "B15")).toBe(true);
    expect(defines("- **Answer 4:** only a box recorded as mixed ranks first", "answer 4")).toBe(true);
  });

  it("defines every owner's letter and answer the code, the tests, the docs and the config cite", () => {
    const cited = [...files(PLATFORM), ...files(join(ROOT, ".github"))]
      .filter((file) => file !== RECORD)
      .flatMap((file) =>
        scan(readFileSync(file, "utf8").split("\n")).map((c) => ({
          what: c.what,
          where: `${relative(ROOT, file).split(sep).join("/")}:${c.line}`,
        })),
      );
    const missing = new Map<string, string[]>();
    for (const c of cited.filter((c) => !defines(record, c.what))) missing.set(c.what, [...(missing.get(c.what) ?? []), c.where]);
    const report = [...missing.entries()]
      .sort(([a], [b]) => a.localeCompare(b, "en", { numeric: true }))
      .map(([what, wheres]) => `${what} (${wheres.length}): ${wheres.slice(0, 3).join(", ")}${wheres.length > 3 ? ", …" : ""}`);
    expect(report, `${cited.length} citations; these resolve to nothing in review-51.md`).toEqual([]);
  });

  it("names the CLI release by the version the workspace carries", () => {
    const cargo = readFileSync(join(PLATFORM, "Cargo.toml"), "utf8");
    const v = /\[workspace\.package\][^[]*?version\s*=\s*"(\d+)\.(\d+)\.(\d+)"/.exec(cargo)!;
    const version = v.slice(1, 4).join(".");
    // A patch release is x.y.z with z > 0. On 0.x, x.y.0 is a minor, as 0.8.0 is (core's public API broke), so a
    // record that still says "a CLI patch release" must name the version that ships, in a later dated section.
    const saysPatch = /CLI patch release/.test(record);
    expect({ saysPatch, namesVersion: record.includes(version) }).toEqual({
      saysPatch,
      namesVersion: saysPatch && Number(v[3]) === 0 ? true : record.includes(version),
    });
  });

  it("says where the owner's calls went once the backlog's ❓ lines were deleted", () => {
    const backlog = readFileSync(BACKLOG, "utf8");
    const open = backlog.split("\n").filter((l) => l.startsWith("- ❓") && l.includes("review-51.md")).length;
    const later = /^##\s+.*(?:errata|owner's calls|owner's answers)/im.test(record);
    if (/in six ❓ lines that name every ID/.test(record) && !later)
      expect(open, "the backlog's ❓ lines naming review-51.md, which its Left open counts as six").toBe(6);
    if (/None is fixed on the fix branch/.test(record))
      expect(later, "a later dated section on the owner's calls, after 'None is fixed on the fix branch'").toBe(true);
  });
});
