import { describe, expect, it } from "vitest";
import { readAccount } from "../src/background/account";
import { measurable, type KoiosUtxo } from "../src/background/koios";
import { spentRewards, unlocked as unlockedSide, withRewards } from "../src/ui/format";
import { account, CHAINS, publicFunded, type Tested } from "./chain-fixtures";
import { koiosPreprod, vectors } from "./fakes";

const phrase = (words: number) => vectors("cardano_account.json").find((v) => v.account === 0 && v.phrase.split(" ").length === words)!;
const THEIRS = phrase(15).preprod.receive_0 as string;
const STRANGER = "d7".repeat(32);
const OWN_FIVE = `${"e5".repeat(32)}#0`;
const MEASURED: Partial<KoiosUtxo> = { reference_script: { hash: "ab".repeat(28), size: 3, type: "timelock", bytes: "820080" } };
const NATIVE: Partial<KoiosUtxo> = { reference_script: { hash: "ab".repeat(28), size: null, type: "timelock", bytes: null } }; // as Koios gives one

async function strangers(t: Tested, shape: Partial<KoiosUtxo>, value = "5000000") { // as coin-control.test.ts's e8b#1 block
  const [first] = Object.values(koiosPreprod.accounts)[0]!.account_utxos.filter((u) => BigInt(u.value) > 1_000_000_000n);
  const keyHash = await t.wallet.withKeys((keys) => keys.cardano.paymentKeyHash(0, 0));
  t.koios.addedToAccounts.push({ ...first!, tx_hash: STRANGER, tx_index: 0, address: account(12).preprod.receive_0, value,
    payment_cred: keyHash, asset_list: [], block_height: first!.block_height! - 1, ...shape });
}
async function figures(t: Tested) {
  const b = await t.balances.get("preprod");
  const prefs = await t.deps.preferences.get();
  const forms = BigInt(withRewards(unlockedSide(b.cardano), spentRewards(b.cardano.staking, prefs.spendRewards)).lovelace); // Home.tsx:520-521
  const own = await readAccount(t.deps, "preprod");
  const max = await t.send.build("preprod", [{ to: THEIRS, lovelace: null, tokens: [] }]);
  const spends = BigInt(max.payments[0]!.lovelace) + BigInt(max.fee) + BigInt(max.changeLovelace);
  return { forms, own, max, spends };
}
describe("l2still#3", CHAINS, () => {
  it.each([["measurable (round two's shape)", MEASURED], ["native, no bytes", NATIVE]])("with %s chosen before 1.9.2", async (_, shape) => {
    const t = await publicFunded(); await strangers(t, shape); await t.balances.get("preprod", true);
    await t.coins.use("preprod", `${STRANGER}#0`); // as 1.9.1's Set saved it
    const { forms, own, max, spends } = await figures(t);
    expect.soft(own.collateral && `${own.collateral.utxo.tx_hash}#${own.collateral.utxo.tx_index}`).toBe(OWN_FIVE);
    expect.soft(max.inputs).toBe(own.utxos.filter((p) => measurable(p.utxo)).length);
    expect.soft(max.leftOut).toEqual(shape === NATIVE ? [{ txHash: STRANGER, txIndex: 0, reason: "script" }] : []);
    expect.soft(spends, "what Max spends is the forms' 'Max, up to'").toBe(forms);
    const asked = (forms - 4_000_000n).toString();
    await expect.soft(t.send.build("preprod", [{ to: THEIRS, lovelace: asked, tokens: [] }]).then((s) => s.payments[0]!.lovelace)).resolves.toBe(asked);
    await expect.soft(t.moveIn.build("preprod", asked, []).then((m) => m.lovelace)).resolves.toBe(asked);
  });
  it("a stranger's older 5 ₳ native, no choice", async () => {
    const t = await publicFunded(); await strangers(t, NATIVE); await t.balances.get("preprod", true);
    const { forms, spends } = await figures(t); expect.soft(spends).toBe(forms);
  });
  it("a stranger's 10 ₳ native, no choice", async () => {
    const t = await publicFunded(); await strangers(t, NATIVE, "10000000"); await t.balances.get("preprod", true);
    const { forms, spends } = await figures(t); expect.soft(spends).toBe(forms);
  });
});
